const today = new Date().toLocaleDateString('en-PK', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const text = $input.first().json.choices[0].message.content;

let html = text;

// Step 1 — Convert markdown tables to HTML (handles all variations)
const lines = html.split('\n');
let result = [];
let inTable = false;
let tableBuffer = [];

for (const line of lines) {
  const isTableRow = /^\|.+\|$/.test(line.trim());
  const isSeparator = /^\|[\s\-:|\s]+\|$/.test(line.trim());

  if (isSeparator) continue; // skip separator rows entirely

  if (isTableRow) {
    inTable = true;
    tableBuffer.push(line.trim());
  } else {
    if (inTable && tableBuffer.length > 0) {
      // flush table
      let tableHtml = '<table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px;">';
      tableBuffer.forEach((row, i) => {
        const cells = row.split('|').map(c => c.trim()).filter(c => c !== '');
        if (i === 0) {
          tableHtml += '<tr>' + cells.map(c =>
            `<th style="padding:12px 16px;background:#0a5c44;color:white;font-weight:600;border:1px solid #085040;text-align:left;">${c}</th>`
          ).join('') + '</tr>';
        } else {
          const bg = i % 2 === 0 ? '#ffffff' : '#f0faf6';
          tableHtml += '<tr>' + cells.map(c =>
            `<td style="padding:10px 16px;border:1px solid #d0e8e0;background:${bg};color:#333;">${c}</td>`
          ).join('') + '</tr>';
        }
      });
      tableHtml += '</table>';
      result.push(tableHtml);
      tableBuffer = [];
      inTable = false;
    }
    result.push(line);
  }
}

// flush any remaining table
if (tableBuffer.length > 0) {
  let tableHtml = '<table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px;">';
  tableBuffer.forEach((row, i) => {
    const cells = row.split('|').map(c => c.trim()).filter(c => c !== '');
    if (i === 0) {
      tableHtml += '<tr>' + cells.map(c =>
        `<th style="padding:12px 16px;background:#0a5c44;color:white;font-weight:600;border:1px solid #085040;text-align:left;">${c}</th>`
      ).join('') + '</tr>';
    } else {
      const bg = i % 2 === 0 ? '#ffffff' : '#f0faf6';
      tableHtml += '<tr>' + cells.map(c =>
        `<td style="padding:10px 16px;border:1px solid #d0e8e0;background:${bg};color:#333;">${c}</td>`
      ).join('') + '</tr>';
    }
  });
  tableHtml += '</table>';
  result.push(tableHtml);
}

html = result.join('\n');

// Step 2 — Bold
html = html.replace(/\*\*(.*?)\*\*/g, '<strong style="color:#0a5c44;">$1</strong>');

// Step 3 — Italic
html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');

// Step 4 — Headings
html = html.replace(/^### (.+)$/gm, '<h3 style="color:#0a5c44;font-size:15px;margin:18px 0 8px;">$1</h3>');
html = html.replace(/^## (.+)$/gm, '<h2 style="color:#0a5c44;font-size:17px;margin:20px 0 10px;">$1</h2>');
html = html.replace(/^# (.+)$/gm, '<h1 style="color:#0a5c44;font-size:20px;margin:22px 0 12px;">$1</h1>');

// Step 5 — Bullet points
html = html.replace(/^[-*] (.+)$/gm,
  '<div style="display:flex;gap:8px;margin:6px 0;line-height:1.6;"><span style="color:#16a86b;font-weight:700;flex-shrink:0;">•</span><span style="color:#333;">$1</span></div>'
);

// Step 6 — Paragraphs and line breaks
html = html.replace(/\n\n/g, '</p><p style="margin:10px 0;line-height:1.8;color:#333;">');
html = html.replace(/\n/g, '<br>');

const fullHtml = `<!DOCTYPE html>
<html>
<body style="margin:0;padding:0;background:#f0f4f8;font-family:Arial,sans-serif;">
<div style="max-width:620px;margin:40px auto;background:white;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);">

  <div style="background:linear-gradient(135deg,#0a5c44,#16a86b);padding:36px 40px;text-align:center;">
    <div style="font-size:11px;font-weight:600;letter-spacing:3px;color:#a8f0d0;text-transform:uppercase;margin-bottom:10px;">OrderPulse</div>
    <h1 style="color:white;font-size:26px;margin:0 0 8px;font-weight:700;">Daily Orders Report</h1>
    <div style="color:#d0f5e8;font-size:13px;">${today}</div>
  </div>

  <div style="display:flex;background:#f8fdfb;border-bottom:1px solid #d0e8e0;">
    <div style="flex:1;padding:20px;text-align:center;border-right:1px solid #d0e8e0;">
      <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">Platform</div>
      <div style="font-size:18px;font-weight:700;color:#0a5c44;">Shopify</div>
    </div>
    <div style="flex:1;padding:20px;text-align:center;border-right:1px solid #d0e8e0;">
      <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">Powered by</div>
      <div style="font-size:18px;font-weight:700;color:#0a5c44;">Groq AI</div>
    </div>
    <div style="flex:1;padding:20px;text-align:center;">
      <div style="font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:6px;">Frequency</div>
      <div style="font-size:18px;font-weight:700;color:#0a5c44;">Daily</div>
    </div>
  </div>

  <div style="padding:32px 40px;">
    <p style="margin:10px 0;line-height:1.8;color:#333;">${html}</p>
  </div>

  <div style="background:#0a5c44;padding:24px 40px;text-align:center;">
    <div style="color:white;font-size:14px;font-weight:700;margin-bottom:4px;">OrderPulse</div>
    <div style="color:#a8f0d0;font-size:11px;letter-spacing:1px;">Shopify · Groq AI · Notion · Slack · Google Sheets · n8n</div>
  </div>

</div>
</body>
</html>`;

return [{ json: { htmlBody: fullHtml } }];
